mapper.select:
select distinct A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, A.FINPROD_ID object, (CASE WHEN D.OPEN_TYPE = #{openPlanType03} THEN #{openPlanType03} ELSE #{openPlanType01} END) col
from FIN_PRODUCT A INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}, FIN_CASH_INFO C, FIN_OPEN_RULE D where A.OPERATION_TYPE = #{openType,jdbcType=VARCHAR} AND A.FINPROD_ID = C.FINPROD_ID AND C.CASH_ID = D.CASH_ID AND D.OPEN_MODE != #{openMode,jdbcType=VARCHAR}
AND ( A.FINPROD_MARKET_ID like concat('%',#{search},'%') OR A.FINPROD_ABBR like concat('%',#{search},'%') )
